[Form]
public class NDXFlatRateScrap extends FormRun
{
    private ItemGroupId itemGroupId;

    #define.CurrentVersion(1)
    #localmacro.CurrentList
    itemGroupId
    #endmacro

}

public boolean unpack(container _lastValue)
{
    int version = RunBase::getVersion(_lastValue);
    switch(version)
    {
        case #CurrentVersion:
            [version, #CurrentList] = _lastValue;
            return true;
        default:
            return false;
    }

    return false;
}

public void close()
{
    itemGroupId = ItemGroupIdFilter.valueStr();
    xSysLastValue::saveLast(this);
    super();
}

/// <summary>
/// updates BOM and creates BOMScrap record
/// </summary>
/// <param name = "_bom">BOM record</param>
private void doit(BOM _bom)
{
    NDXBOMScrap lNDX_BOMScrap;
    InventTable lInventTable;
    BOM         lBOM;
    ScrapVar    scrapVarSave;


    // Stücklistenposition ändern
    select firstonly forUpdate lBOM 
        where lBOM.RecId == _bom.RecId;

    lInventTable = InventTable::find(_bom.ItemId);

    scrapVarSave  = lBOM.ScrapVar;
    lBOM.ScrapVar = lInventTable.ScrapVar;

    ttsbegin;
    if (lBOM.validateWrite())
    {
        lBOM.update();

        lNDX_BOMScrap = NDXBOMScrap::findOrCreate(_bom.RecId, true);

        lNDX_BOMScrap.ValueChanged  = NoYes::Yes;
        lNDX_BOMScrap.ScrapVarOld   = ScrapVarSave;
        lNDX_BOMScrap.update();
    }
    ttscommit;
}

/// <summary>
/// Starts the change operation for BOM record
/// </summary>
void change_BOMScrap()
{
    BOM lBOM;
    int nAnz;

    // falls ohne Markierung -> alle zum ändern markierten Datensätze durchlaufen
    if (BOM_DS.anyMarked())
    {
        lBOM = BOM_DS.getFirst(1);

        while(lBOM)
        {
            ++nAnz;
            this.doit(lBOM);
            lBOM = BOM_DS.getNext();
        }
    }

    info(strfmt("@NDX:NDXFlatRateNumberOfChanges", nAnz));         // Der variable Ausschuss wurde bei [%1] Stücklistenpositionen geändert!
    BOM_DS.executeQuery();

}

public void run()
{
    super();

    xSysLastValue::getLast(this);
    ItemGroupIdFilter.text(itemGroupId);
    InventTable_DS.executeQuery();
}

public void executeQuery()
{
    QueryBuildDataSource qbds = this.query().dataSourceTable(tableNum(InventItemGroupItem));
    qbds.clearRanges();

    if(ItemGroupIdFilter.valueStr() != '')
    {
        qbds.addRange(fieldNum(InventItemGroupItem, ItemGroupId)).value(ItemGroupIdFilter.valueStr());
    }

    super();
}

public boolean modified()
{
    boolean ret;

    ret = super();

    InventTable_DS.executeQuery();

    return ret;
}
